package source_test

import (
	"os"
	"path/filepath"
	"testing"

	"codetospec/internal/source"
)

func TestWalkMarksGeneratedFiles(t *testing.T) {
	cases := map[string]struct {
		src  string
		want bool
	}{
		"go generate header": {
			"// Code generated by componentgen, DO NOT EDIT.\n\npackage componentgen\n", true,
		},
		"header after a build constraint": {
			"//go:build linux\n\n// Code generated by stringer; DO NOT EDIT.\npackage x\n", true,
		},
		"generator holding the header in a string": {
			"package main\n\nconst header = `// Code generated by componentgen, DO NOT EDIT.`\n", false,
		},
		"header after the package clause": {
			"package x\n\n// Code generated by hand, DO NOT EDIT.\n", false,
		},
		"ordinary file": {"// Package x does things.\npackage x\n", false},
	}
	root := t.TempDir()
	names := map[string]string{}
	i := 0
	for name, tc := range cases {
		file := filepath.Join(root, string(rune('a'+i))+".go")
		i++
		if err := os.WriteFile(file, []byte(tc.src), 0o600); err != nil {
			t.Fatal(err)
		}
		names[filepath.Base(file)] = name
	}
	files, err := source.Walk(root, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != len(cases) {
		t.Fatalf("walked %d files, want %d", len(files), len(cases))
	}
	for _, f := range files {
		name := names[f.Path]
		t.Run(name, func(t *testing.T) {
			if f.Generated != cases[name].want {
				t.Fatalf("Generated = %v, want %v", f.Generated, cases[name].want)
			}
		})
	}
}
